import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side','price','qty','time'}
    buy_heap = []  # (-price, time, id)
    sell_heap = []  # (price, time, id)
    time_counter = 0

    def add_buy(oid):
        entry = book[oid]
        heapq.heappush(buy_heap, (-entry['price'], entry['time'], oid))

    def add_sell(oid):
        entry = book[oid]
        heapq.heappush(sell_heap, (entry['price'], entry['time'], oid))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        time_counter += 1
        remaining = qty

        if side == 'buy':
            heap = sell_heap
            while remaining > 0 and heap:
                p, t, sid = heap[0]
                if sid not in book or book[sid]['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if typ != 'market' and p > price:
                    break
                heapq.heappop(heap)
                sqty = book[sid]['qty']
                trade_qty = min(remaining, sqty)
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                book[sid]['qty'] -= trade_qty
                if book[sid]['qty'] > 0:
                    heapq.heappush(heap, (p, t, sid))
                else:
                    del book[sid]
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'time': time_counter}
                add_buy(oid)
        else:  # sell
            heap = buy_heap
            while remaining > 0 and heap:
                negp, t, bid = heap[0]
                p = -negp
                if bid not in book or book[bid]['qty'] <= 0:
                    heapq.heappop(heap)
                    continue
                if typ != 'market' and p < price:
                    break
                heapq.heappop(heap)
                bqty = book[bid]['qty']
                trade_qty = min(remaining, bqty)
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                book[bid]['qty'] -= trade_qty
                if book[bid]['qty'] > 0:
                    heapq.heappush(heap, (negp, t, bid))
                else:
                    del book[bid]
            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'time': time_counter}
                add_sell(oid)

    return trades

